from auth0tf.secrets import COMPUTED_FIELDS, classify_field, is_write_only


def test_computed_client_secret_is_computed():
    assert classify_field("auth0_client", "client_secret") == "computed"


def test_resource_server_signing_secret_is_computed():
    assert classify_field("auth0_resource_server", "signing_secret") == "computed"


def test_client_id_is_computed():
    # client_id is generated by Auth0 in the new tenant, never set it
    assert classify_field("auth0_client", "client_id") == "computed"


def test_client_credentials_secret_is_computed():
    # Auth0 owns the client_credentials secret; it sits in state
    assert classify_field("auth0_client_credentials", "client_secret") == "computed"


def test_computed_registry_shape():
    assert ("auth0_client", "client_secret") in COMPUTED_FIELDS


def test_names_containing_token_or_secret_are_plain():
    # Name matching used to flag these as secrets and bind them to a lookup that
    # then failed at plan time. Classification is now an explicit table.
    assert classify_field("auth0_resource_server", "token_lifetime") == "plain"
    assert classify_field("auth0_resource_server", "token_dialect") == "plain"
    assert classify_field(
        "auth0_resource_server", "token_lifetime_for_anonymous_access_tokens") == "plain"
    assert classify_field("auth0_client", "is_token_endpoint_ip_header_trusted") == "plain"


def test_write_only_fields_are_never_emitted():
    # `*_wo` / `*_wo_version` are classified computed (= skipped) for ANY type,
    # because a `_wo_version` without its `_wo` pair fails provider validation.
    for field in ("secrets_wo_version", "client_secret_wo", "client_secret_wo_version",
                  "options_client_secret_wo", "options_client_secret_wo_version",
                  "datadog_api_key_wo_version"):
        assert is_write_only(field)
        assert classify_field("auth0_anything", field) == "computed"


def test_listed_input_field_is_input():
    assert classify_field("auth0_flow_vault_connection", "setup") == "input"


def test_generator_bookkeeping_fields_are_internal():
    assert classify_field("auth0_action", "secret_names") == "internal"
    assert classify_field("auth0_connection", "secret_names") == "internal"
